Lemma rmrep_group_hdr_zero : ltac2:(zQ "i80!hf!jh7!jha!h9!q6!jj3!io1!jjd!s3!jk2!m3!jk9!jl1!im1!jm0!jo3!jp2!jp9!jpf!jq8!jqf!jr5!u0!jrb!hhd!hr5!js0!jsb!jt8!ju3!jub!jv8!ig0!kg6!o3!ih7!ihc!kh2!ip7!khc>2st$i0>1m>0@1$4@1$3#k0@1$8@1$4@1$3#8>1p@2$9$1$0>2gh$2>2bs@1$h3@1$4@1$3#8>0@4$a?5HCEIL?4HSEC^5^4>0@3$7@1$8$2@6$i5@2$9$1$0$2@4$i6$b@4$f$1$5$0$6@6$e$1$5$c$0$6$d$2@4$i7$b@4$f$1$5$0$6@6$e$1$5$c$0$6$d$2^4@1$i1^6@2$h0$2^3>0>1o$0>0@2$h6@2$i3Z^1@2$i4^1+c@2$h7$0\1h$0@3$7$hc@2$hb@2$hf^a@3$h1$1$0^8@2$i2@3$h5$1$0^8^3@1$ha^1>0@3$7$h4@2$h2@1$4@1$3#8^4N8@4$a?5HCEIL?4HSEC@2$he^7^9@3$h8^8@1$h9@2$hd^9^7^5").
Proof.
  intros st m p gh bs REP Hg HU Hlen.
  pose proof (rmrep_del_group st m p REP) as REP'.
  destruct REP as (WF & _).
  destruct WF as (Hres & WR & DJ & WA & WG).
  destruct (WG p gh Hg) as (r & Hr & K & P0 & P1 & PA).
  destruct (WR p.1 r Hr) as (B0 & _ & _ & BH & RF).
  destruct (rreserved_disjoint _ _ RF) as (_ & _ & D3 & D4).
  pose proof (@hceil_range HCEIL) as HC.
  assert (CA : conc st p = r_base r + p.2) by (unfold conc, get_region; rewrite Hr; reflexivity).
  assert (LR : lr_lo r = r_base r) by (unfold lr_lo; rewrite K; reflexivity).
  assert (Hconc : forall q, conc (del_group p st) q = conc st q) by (intros q; reflexivity).
  assert (Hsh : forall rid, get_shadow (del_group p st) rid = get_shadow st rid) by (intros rid; reflexivity).
  eapply (rmrep_transport_unowned (del_group p st) m (write_to_mem m (wa (conc st p)) bs)
            [(conc st p, conc st p + 8)]).
  - exact REP'.
  - apply munch_write.
    + intros x _; reflexivity.
    + lia.
    + rewrite Hlen. change (Z.of_nat 8) with 8. lia.
    + rewrite Hlen. change (Z.of_nat 8) with 8. cbn [inside]. left. lia.
  - apply wmono_write. intros x H. exact H.
  - apply ivs_avoid_cons; [| apply ivs_avoid_nil].
    intros a Ha Hf. unfold rrepfoot in Hf.
    destruct Hf as [Hf | [Hf | [Hf | [Hf | [Hf | [Hf | [Hf | [Hf | [Hf | Hf]]]]]]]]].
    + unfold RCTX in Hf. lia.
    + unfold RMLOCK in Hf. lia.
    + unfold RNEED_LOCKS in Hf. lia.
    + unfold RPAGE_SIZE in Hf. lia.
    + (* an area: it lies in a region of another kind, disjoint from the group's region *)
      destruct Hf as (ak & ar & Ha' & Hin). rewrite Hconc in Hin. cbn [del_group set_groups s_areas] in Ha'.
      destruct (WA ak ar Ha') as (ra & Hra & A0 & A1 & _ & KA & LA).
      assert (Ca : conc st ak = r_base ra + ak.2) by (unfold conc, get_region; rewrite Hra; reflexivity).
      assert (NE : p.1 <> ak.1) by (intros E; rewrite E in Hr; congruence).
      destruct (DJ p.1 r ak.1 ra Hr Hra NE) as [E | E]; lia.
    + (* another group header: same region at another 16-aligned offset, or a disjoint region *)
      destruct Hf as (b & gb & Hb & Hin). rewrite Hconc in Hin.
      cbn [del_group set_groups s_groups] in Hb. apply lookup_delete_Some in Hb. destruct Hb as (Hpb & Hb).
      destruct (WG b gb Hb) as (rb & Hrb & KB & Q0 & Q1 & QA).
      assert (Cb : conc st b = r_base rb + b.2) by (unfold conc, get_region; rewrite Hrb; reflexivity).
      destruct (N.eq_dec p.1 b.1) as [E | NE].
      * assert (Erb : rb = r) by (rewrite E in Hr; congruence). subst rb.
        assert (p.2 <> b.2) by (intros E2; apply Hpb; apply injective_projections; [exact E | exact E2]).
        Z.div_mod_to_equations. lia.
      * assert (LRb : lr_lo rb = r_base rb) by (unfold lr_lo; rewrite KB; reflexivity).
        destruct (DJ p.1 r b.1 rb Hr Hrb NE) as [E | E]; lia.
    + (* a known shadow byte: in the group's own region the header bytes are Unknown, other regions are disjoint *)
      destruct Hf as (rid & r' & v & Hr' & K' & Hin & Hk).
      cbn [del_group set_groups s_regions] in Hr'. rewrite Hsh in Hk.
      destruct (N.eq_dec p.1 rid) as [E | NE].
      * rewrite <- E in Hr', Hk. assert (Er : r' = r) by congruence. subst r'.
        destruct (HU (a - r_base r - p.2)) as (h & Hh); [lia |].
        replace (p.2 + (a - r_base r - p.2)) with (a - r_base r) in Hh by lia.
        rewrite Hh in Hk. discriminate.
      * assert (LR' : lr_lo r' = r_base r') by (unfold lr_lo; rewrite K'; reflexivity).
        destruct (DJ p.1 r rid r' Hr Hr' NE) as [E | E]; lia.
    + unfold RGOT_SSP in Hf. lia.
    + unfold RSSP_GUARD in Hf. lia.
    + lia.
Qed.

